package com.mavis.platform.auth.service;
import com.mavis.common.exception.*;import com.mavis.common.utils.HashUtils;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Propagation;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;
@Service @RequiredArgsConstructor public class AuthAbuseGuard{
 private final JdbcTemplate jdbc;
 public void check(String scope,String subject){Boolean blocked=jdbc.queryForObject("SELECT coalesce((SELECT blocked_until>now() FROM auth_rate_limits WHERE scope=? AND subject_digest=?),false)",Boolean.class,scope,digest(subject));if(Boolean.TRUE.equals(blocked))throw new BusinessException(ErrorCode.TOO_MANY_REQUESTS,"AUTH_RATE_LIMITED","Too many attempts. Try again later");}
 @Transactional(propagation=Propagation.REQUIRES_NEW) public void failure(String scope,String subject){jdbc.update("INSERT INTO auth_rate_limits(scope,subject_digest,attempts) VALUES (?,?,1) ON CONFLICT(scope,subject_digest) DO UPDATE SET attempts=CASE WHEN auth_rate_limits.window_started_at<now()-interval '15 minutes' THEN 1 ELSE auth_rate_limits.attempts+1 END,window_started_at=CASE WHEN auth_rate_limits.window_started_at<now()-interval '15 minutes' THEN now() ELSE auth_rate_limits.window_started_at END,blocked_until=CASE WHEN (CASE WHEN auth_rate_limits.window_started_at<now()-interval '15 minutes' THEN 1 ELSE auth_rate_limits.attempts+1 END)>=5 THEN now()+interval '15 minutes' ELSE auth_rate_limits.blocked_until END",scope,digest(subject));jdbc.update("INSERT INTO audit_logs(action,target_type,details) VALUES ('AUTH_FAILURE','AUTH',jsonb_build_object('scope',?))",scope);}
 @Transactional(propagation=Propagation.REQUIRES_NEW) public void success(String scope,String subject,java.util.UUID actor){jdbc.update("DELETE FROM auth_rate_limits WHERE scope=? AND subject_digest=?",scope,digest(subject));jdbc.update("INSERT INTO audit_logs(actor_id,action,target_type) VALUES (?,'AUTH_SUCCESS','AUTH')",actor);}
 private static String digest(String s){return HashUtils.sha256Hex(s.trim().toLowerCase().getBytes(StandardCharsets.UTF_8));}
}
